IGJwcCxFeGNlcHRpb25JbmZvICpleGNlcHRpb24pCiAgIEJJbWdCdWZmPSh1bnNpZ25lZCBjaGFy
ICopIEFjcXVpcmVRdWFudHVtTWVtb3J5KChzaXplX3QpIGxkYmxrLAogICAgIDgqc2l6ZW9mKCpC
